 return {points,weeklyChange:weekly,newsAdjustment:newsShift,asOf:now,priceAgeDays:age,method:fit.trained?'ridge + local momentum':'local momentum fallback',validation:fit.trained?{weeks:fit.holdout,mae:fit.mae,baselineMAE:fit.naiveMAE,trainingWeeks:fit.rows}:null,scope:history.description,historyScope:history.scope,inputs:{localWeekly:local,marketWeekly:prediction,newsScore},drivers:[{name:'Local price momentum',weekly:local*.3},...fit.markets.map((m,i)=>({name:m.label,weekly:fit.trained?(fit.coeff[i+1]||0)*inputs[i+1]*.7:0})),{name:'Headline stress cue',weekly:newsShift}],warning:'Scenarios are approximate lower/central/upper paths using historical weekly residuals, not guaranteed probabilities. News adjustment is a bounded keyword heuristic; it is not backtested.'};
