export async function cityData(state,name,ctx){let [prices,signal,h]=await Promise.all([statePrices(state,ctx),signals(ctx),history(state,name,ctx)]);let price=name?prices.metros.find(m=>norm(m.name)===norm(name)):prices.stateAverage;if(!price)throw Error('Metro not found in the current AAA table. Choose an available metro.');let geo=CITIES.find(c=>c.state===state&&norm(c.name)===norm(name));return {price,location:geo||null,source:prices.source,retrievedAt:prices.retrievedAt,history:h,signals:signal,forecast:forecast(price,h,signal),generatedAt:new Date().toISOString(),coverage:name?'metro':'state'};}
export async function geocode(q,ctx){return cached('geo-'+q.toLowerCase(),604800,ctx,async()=>{let u=new URL('https://photon.komoot.io/api/');u.searchParams.set('q',q);u.searchParams.set('limit','8');u.searchParams.set('lang','en');let j=JSON.parse(await text(u));let seen=new Set();return (j.features||[]).filter(f=>f.properties.countrycode==='US').map(f=>{let p=f.properties,[lon,lat]=f.geometry.coordinates,state=Object.entries(STATES).find(([code,name])=>name===p.state||code===p.state)?.[0];return {name:p.city||p.name||p.county,state,lat,lon,label:[p.name,p.city,p.state,p.postcode].filter(Boolean).filter((x,i,a)=>a.indexOf(x)===i).join(', ')};}).filter(p=>{let k=p.name+p.state;if(!p.state||seen.has(k))return false;seen.add(k);return true;});});}
export async function mapData(ctx){const [signal,h]=await Promise.all([signals(ctx),history('US','',ctx).catch(()=>history('NY','New York',ctx))]);let fitted=model(h,signal.markets);let groups=[...new Set(CITIES.map(c=>c.state))],states={};for(let i=0;i<groups.length;i+=5){let result=await Promise.allSettled(groups.slice(i,i+5).map(s=>statePrices(s,ctx)));result.forEach((r,j)=>{if(r.status==='fulfilled')states[groups[i+j]]=r.value;});}let cities=[];for(let c of CITIES){let s=states[c.state],price=s?.metros.find(m=>norm(m.name)===norm(c.name));if(!price)continue;cities.push({...c,price,source:s.source,forecast:forecast(price,h,signal,today(),fitted)});}return {cities,failedStates:groups.filter(s=>!states[s]),generatedAt:new Date().toISOString(),modelScope:h.description};}

const page = "<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#eff3ed\"><title>CheapAssGas · Local fuel outlook</title><meta name=\"description\" content=\"Actual metro gas averages, historical and market trends, and daily fuel price scenarios on an interactive map.\">\n<link rel=\"stylesheet\" href=\"https://unpkg.com/leaflet@1.9.4/dist/leaflet.css\">\n<style>\n:root{--bg:#eff3ed;--panel:#fff;--ink:#1b3029;--muted:#687b71;--line:#dce5dc;--green:#257657;--red:#b75344;--blue:#547eab;--amber:#ac7635}*{box-sizing:border-box}body{margin:0;font-family:system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;background:var(--bg);color:var(--ink);font-size:14px}button,input,select{font:inherit;color:inherit}button,select{cursor:pointer}button:disabled{cursor:wait;opacity:.6}a{color:var(--green)}button,input,select{border:1px solid var(--line);border-radius:9px;background:#fff;padding:10px 13px}button:hover{background:#eef5ef}button:focus-visible,input:focus-visible,select:focus-visible,a:focus-visible{outline:3px solid #98bfaf;outline-offset:2px}.container{max-width:1420px;margin:auto;padding:0 30px 40px}header{display:flex;align-items:center;justify-content:space-between;gap:10px;height:76px;border-bottom:1px solid var(--line)}.brand{font-size:21px;font-weight:800;letter-spacing:-1px;display:flex;align-items:center;gap:10px}.brand i{font-style:normal;width:33px;height:33px;background:var(--ink);color:white;display:grid;place-items:center;border-radius:10px}.tag{font-size:11px;padding:5px 8px;background:#deebe1;border-radius:6px;font-weight:600}.eyebrow{font-size:10px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;color:var(--muted)}.intro{padding:27px 0 19px;display:flex;align-items:flex-end;justify-content:space-between;gap:16px}h1{margin:7px 0;font-size:32px;letter-spacing:-1.3px;line-height:1.15}.muted{color:var(--muted);font-size:12px;line-height:1.65}.locations{display:grid;grid-template-columns:1.4fr 1fr 1.3fr auto;gap:10px;margin-bottom:14px}.search{display:flex;gap:6px}.search input{width:100%;min-width:0}select{width:100%;min-width:0}.status{padding:10px 13px;border:1px solid var(--line);border-radius:9px;background:#e6eee4;color:#54705c;font-size:12px;line-height:1.5;margin-bottom:16px;min-height:38px}.status.error{background:#faece7;color:#954638}.results{display:flex;gap:6px;flex-wrap:wrap;margin:0 0 12px}.results:empty{display:none}.results button{font-size:12px}.metrics{display:grid;grid-template-columns:1.1fr 1fr 1fr 1.1fr;gap:13px;margin-bottom:17px}.card{background:var(--panel);border:1px solid var(--line);border-radius:15px;padding:21px;min-width:0}.metric-label{font-size:11px;color:var(--muted);margin-bottom:8px}.metric-number{font-weight:750;font-size:32px;letter-spacing:-1.1px;font-variant-numeric:tabular-nums}.metric-number.small{font-size:23px}.metric-detail{font-size:11px;color:var(--muted);line-height:1.6;margin-top:6px}.up{color:var(--red)}.down{color:var(--green)}.twocol{display:grid;grid-template-columns:1.05fr 1fr;gap:17px}.cardhead{display:flex;align-items:flex-start;justify-content:space-between;gap:14px;margin-bottom:15px}h2{font-size:17px;letter-spacing:-.4px;margin:0 0 4px}h3{font-size:14px;margin:0 0 7px}.pill{font-size:10px;border:1px solid var(--line);border-radius:30px;padding:5px 9px;white-space:nowrap;color:var(--muted)}.legend{display:flex;flex-wrap:wrap;gap:13px;font-size:11px;color:var(--muted);margin:12px 0}.legend span{display:flex;align-items:center;gap:5px}.legend i{display:block;width:17px;height:3px;background:var(--green)}.legend .average{background:var(--blue)}.legend .negative{background:var(--red)}.chartbox{height:230px;width:100%;position:relative}.chartbox svg{width:100%;height:100%;display:block}.chartbox.small{height:140px}.chart-empty{height:100%;display:grid;place-items:center;font-size:12px;color:var(--muted);text-align:center}.chart-grid{stroke:#e7eee5;stroke-width:1}.chart-axis{font-size:10px;fill:#819084;font-family:system-ui,sans-serif}.chart-path{fill:none;stroke-width:2.8;stroke-linejoin:round;stroke-linecap:round}.day-controls{margin-top:10px;border-top:1px solid var(--line);padding-top:13px}.day-controls label{font-size:12px;font-weight:650;display:flex;justify-content:space-between}.day-controls input{width:100%;padding:0;border:0;accent-color:var(--green);margin:13px 0 6px}.dayends{display:flex;justify-content:space-between;font-size:10px;color:var(--muted)}.scenarios{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:13px}.scenario{padding:10px;border-radius:9px;background:#f2f7f1}.scenario strong{font-size:20px;display:block;font-variant-numeric:tabular-nums;margin:4px 0}.scenario .label{font-size:10px}.scenario.blue{background:#eef3f8}.scenario.red{background:#faefeb}.section{margin-top:22px}.map-toolbar{display:flex;gap:8px;margin-bottom:11px}.map-toolbar select{flex:1;font-size:12px;padding:8px}.map-toolbar button{font-size:12px;padding:8px 11px}#map{height:333px;border-radius:11px;position:relative;background:#e1eadd;z-index:0}.leaflet-container{font:12px system-ui,sans-serif}.price-pin{background:#fff;border:2px solid var(--green);padding:5px 9px;border-radius:18px;white-space:nowrap;font-size:12px;font-weight:750;box-shadow:0 3px 9px #152a1d25;line-height:1.2}.price-pin.selected{color:white;background:var(--green)}.price-pin.negative{border-color:var(--red)}.price-pin.average{border-color:var(--blue)}.map-note{font-size:10px;color:var(--muted);margin-top:10px;line-height:1.65}.daily-table-wrap{overflow-x:auto;max-height:338px;overflow-y:auto}table{border-collapse:collapse;width:100%;font-size:12px;white-space:nowrap}th{text-align:right;font-size:10px;color:var(--muted);font-weight:600;background:white;position:sticky;top:0;padding:11px;border-bottom:1px solid var(--line)}td{padding:10px 11px;text-align:right;border-bottom:1px solid #edf1eb;font-variant-numeric:tabular-nums}td:first-child,th:first-child{text-align:left}tr.active td{background:#edf5ef;font-weight:700}tbody tr{cursor:pointer}tbody tr:hover td{background:#f5f8f1}.split{display:grid;grid-template-columns:1.25fr 1fr;gap:17px}.range-tabs{display:flex;gap:4px}.range-tabs button{font-size:10px;padding:5px 8px;border:0;background:#f2f5ef}.range-tabs button.active{color:white;background:var(--green)}.market-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:13px}.market-top{display:flex;align-items:center;justify-content:space-between;gap:10px}.market-num{font-size:23px;font-weight:700;margin:12px 0 2px;letter-spacing:-.7px}.market-change{font-size:11px;font-weight:650}.market-card .chartbox{height:105px;margin-top:10px}.news-layout{display:grid;grid-template-columns:.85fr 1.15fr;gap:17px}.news-list{list-style:none;padding:0;margin:0}.news-list li{border-bottom:1px solid var(--line);padding:11px 0}.news-list li:last-child{border:0}.news-list a{font-size:12px;font-weight:600;line-height:1.55;text-decoration:none;color:var(--ink)}.news-list a:hover{text-decoration:underline}.news-meta{font-size:10px;color:var(--muted);margin-top:5px}.drivers{display:flex;flex-direction:column;gap:12px}.driver{display:flex;justify-content:space-between;gap:10px;font-size:11px}.driver strong{font-variant-numeric:tabular-nums}.source-footer{margin-top:22px;padding-top:17px;border-top:1px solid var(--line);font-size:11px;color:var(--muted);line-height:1.8}.source-footer a{margin-right:10px}.load{animation:pulse 1s infinite alternate}@keyframes pulse{to{opacity:.5}}[hidden]{display:none!important}dialog{border:1px solid var(--line);border-radius:18px;padding:26px;max-width:660px;width:calc(100% - 32px);color:var(--ink)}dialog::backdrop{background:#14332366}dialog p,dialog li{font-size:13px;line-height:1.7}dialog h2{font-size:23px}.dialog-close{float:right}body.loading .data{opacity:.5;pointer-events:none}.loading-note{font-size:12px;color:var(--muted)}@media(max-width:1000px){.container{padding-inline:20px}.locations{grid-template-columns:1fr 1fr}.metrics{grid-template-columns:repeat(2,1fr)}.twocol,.split{grid-template-columns:1fr}.market-grid{grid-template-columns:repeat(3,1fr)}#map{height:390px}}@media(max-width:650px){.container{padding:0 14px 30px}header{height:65px}.brand{font-size:19px}header .tag{display:none}.intro{padding-top:23px;align-items:flex-start}h1{font-size:28px}.intro>button{padding:8px 9px;font-size:11px}.locations{grid-template-columns:1fr 1fr;gap:8px}.search{grid-column:1/-1}.locate{grid-column:1/-1}.card{padding:16px;border-radius:13px}.metrics{gap:9px}.metric-number{font-size:29px}.metric-number.small{font-size:20px}.twocol,.split,.news-layout{grid-template-columns:1fr;gap:13px}.market-grid{grid-template-columns:1fr}.market-card{display:grid;grid-template-columns:1fr 1fr;gap:0 12px}.market-card .market-top{grid-column:1/-1}.market-card .chartbox{grid-column:2;grid-row:2/5;height:95px}.market-card .market-bottom{grid-column:1/-1}.chartbox{height:215px}#map{height:345px}.scenarios{gap:6px}.scenario{padding:9px 7px}.scenario strong{font-size:18px}.pill{font-size:9px;padding:4px 7px}.news-layout{gap:13px}.status{font-size:11px}.section{margin-top:17px}}\n</style></head><body><main class=\"container\">\n<header><div class=\"brand\"><i>$</i>cheapassgas</div><span class=\"tag\">Real observations. Transparent projections.</span><button id=\"refresh\" aria-label=\"Refresh data\">↻ Refresh</button></header>\n<section class=\"intro\"><div><div class=\"eyebrow\">CITY FUEL INTELLIGENCE · UNITED STATES</div><h1 id=\"title\">Your local fuel outlook</h1><div class=\"muted\" id=\"subtitle\">Choose a city to see actual gas averages and daily scenarios.</div></div><button id=\"methodBtn\">How forecasts work ↗</button></section>\n<section class=\"locations\" aria-label=\"Choose your location\"><form class=\"search\" id=\"searchForm\"><input id=\"query\" placeholder=\"Search city or ZIP code\" aria-label=\"US city or ZIP code\" maxlength=\"100\"><button type=\"submit\">Search</button></form><select id=\"state\" aria-label=\"State\"></select><select id=\"metro\" aria-label=\"Metro area\"><option>Loading metro areas…</option></select><button class=\"locate\" id=\"locate\">◎ Use my location</button></section>\n<div class=\"results\" id=\"searchResults\"></div><div class=\"status\" id=\"status\" role=\"status\" aria-live=\"polite\">Connecting to AAA, EIA, and market feeds…</div>\n<section class=\"metrics data\"><article class=\"card\"><div class=\"metric-label\">Observed regular gas · per gallon</div><div class=\"metric-number\" id=\"price\">—</div><div class=\"metric-detail\" id=\"priceDate\">Awaiting source data</div></article><article class=\"card\"><div class=\"metric-label\">Change since last week</div><div class=\"metric-number\" id=\"weekChange\">—</div><div class=\"metric-detail\" id=\"monthChange\">AAA metro average</div></article><article class=\"card\"><div class=\"metric-label\" id=\"estimateLabel\">Average projection · selected day</div><div class=\"metric-number\" id=\"estimate\">—</div><div class=\"metric-detail\" id=\"estimateDetail\">14 day outlook</div></article><article class=\"card\"><div class=\"metric-label\">Historical forecast error</div><div class=\"metric-number small\" id=\"validation\">—</div><div class=\"metric-detail\" id=\"validationDetail\">Measured on held-out weeks</div></article></section>\n<section class=\"twocol data\"><article class=\"card\"><div class=\"cardhead\"><div><h2>Three paths for the days ahead</h2><div class=\"muted\">Positive means lower prices. Negative means higher prices.</div></div><span class=\"pill\">14 DAYS</span></div><div class=\"legend\"><span><i></i>Positive / lower</span><span><i class=\"average\"></i>Average</span><span><i class=\"negative\"></i>Negative / higher</span></div><div class=\"chartbox\" id=\"forecastChart\"></div><div class=\"day-controls\"><label for=\"day\">Explore a day <span id=\"dayLabel\">Today</span></label><input id=\"day\" type=\"range\" min=\"0\" max=\"14\" value=\"1\" step=\"1\"><div class=\"dayends\"><span>Today</span><span>+7 days</span><span>+14 days</span></div></div><div class=\"scenarios\"><div class=\"scenario\"><span class=\"label\">POSITIVE</span><strong id=\"positive\">—</strong><span class=\"muted\">Lower price path</span></div><div class=\"scenario blue\"><span class=\"label\">MEDIAN</span><strong id=\"average\">—</strong><span class=\"muted\">Central estimate</span></div><div class=\"scenario red\"><span class=\"label\">NEGATIVE</span><strong id=\"negative\">—</strong><span class=\"muted\">Higher price path</span></div></div><p class=\"map-note\" id=\"forecastNote\">Daily projections will appear when observed prices are available.</p></article>\n<article class=\"card\"><div class=\"cardhead\"><div><h2>Projected prices on the map</h2><div class=\"muted\" id=\"mapDate\">Pan, zoom, and tap a metro.</div></div><span class=\"pill\" id=\"mapCount\">Loading</span></div><div class=\"map-toolbar\"><select id=\"scenario\" aria-label=\"Map outlook scenario\"><option value=\"average\">Average outlook</option><option value=\"positive\">Positive · lower prices</option><option value=\"negative\">Negative · higher prices</option></select><button id=\"centerMap\">My metro</button><button id=\"allMap\">US view</button></div><div id=\"map\" aria-label=\"Interactive map of metro gas-price projections\"></div><p class=\"map-note\" id=\"mapNote\">Loading real metro prices…</p></article></section>\n<section class=\"section split data\"><article class=\"card\"><div class=\"cardhead\"><div><h2>Day by day</h2><div class=\"muted\">Regular gas · dollars per gallon · select a row to explore</div></div></div><div class=\"daily-table-wrap\"><table><thead><tr><th>Date</th><th>Positive ↓</th><th>Average</th><th>Negative ↑</th></tr></thead><tbody id=\"dailyTable\"></tbody></table></div></article><article class=\"card\"><div class=\"cardhead\"><div><h2>What feeds the outlook</h2><div class=\"muted\">Estimated weekly contributions to the central path</div></div></div><div class=\"drivers\" id=\"drivers\"></div><p class=\"map-note\" id=\"modelScope\"></p><div class=\"status\" id=\"dataIssues\" style=\"margin:16px 0 0\">Checking feed coverage…</div></article></section>\n<section class=\"section card data\"><div class=\"cardhead\"><div><h2>Actual price history</h2><div class=\"muted\" id=\"historyScope\">EIA weekly observations</div></div><div class=\"range-tabs\" id=\"historyTabs\"><button data-days=\"30\">1M</button><button data-days=\"90\" class=\"active\">3M</button><button data-days=\"180\">6M</button><button data-days=\"365\">1Y</button></div></div><div class=\"chartbox\" id=\"historyChart\"></div><div class=\"map-note\" id=\"historyDate\"></div></section>\n<section class=\"section\"><div class=\"cardhead\"><div><h2>Oil, wholesale gas & energy stocks</h2><div class=\"muted\">Actual daily market observations · last 90 days</div></div></div><div class=\"market-grid data\" id=\"marketGrid\"><div class=\"card loading-note\">Loading market series…</div></div></section>\n<section class=\"section news-layout data\"><article class=\"card\"><div class=\"cardhead\"><div><h2>News media pulse</h2><div class=\"muted\">Articles in the retrieved feed, by day</div></div><span class=\"pill\">14 DAYS</span></div><div class=\"chartbox small\" id=\"newsChart\"></div><div class=\"scenarios\"><div class=\"scenario red\"><span class=\"label\">UPWARD CUES</span><strong id=\"newsUp\">—</strong></div><div class=\"scenario\"><span class=\"label\">DOWNWARD CUES</span><strong id=\"newsDown\">—</strong></div><div class=\"scenario blue\"><span class=\"label\">RECENT ARTICLES</span><strong id=\"newsTotal\">—</strong></div></div><p class=\"map-note\" id=\"newsScope\">Keyword cues describe headlines. They do not measure full article sentiment.</p></article><article class=\"card\"><div class=\"cardhead\"><div><h2>Reporting behind the signals</h2><div class=\"muted\" id=\"newsSource\">Source-linked, dated fuel and oil reporting</div></div></div><ul class=\"news-list\" id=\"newsList\"></ul></article></section>\n<footer class=\"source-footer\"><strong>Coverage:</strong> AAA daily metro averages where published, with an explicit state fallback. These are area averages, not individual station quotes. EIA history may cover a broader area and is identified above. Market feeds may be delayed or temporarily unavailable. Projections are estimates, not guaranteed prices.<br><a href=\"https://gasprices.aaa.com/\" target=\"_blank\" rel=\"noopener\">AAA prices</a><a href=\"https://www.eia.gov/petroleum/gasdiesel/\" target=\"_blank\" rel=\"noopener\">EIA history</a><a href=\"https://finance.yahoo.com/\" target=\"_blank\" rel=\"noopener\">Yahoo market data</a><a href=\"https://www.gdeltproject.org/\" target=\"_blank\" rel=\"noopener\">GDELT</a><span id=\"retrieval\"></span></footer>\n</main><dialog id=\"method\"><button class=\"dialog-close\" id=\"closeMethod\">Close</button><h2>How this outlook is calculated</h2><p>The observed starting price is AAA's published regular gasoline metro average, with its actual source date. If your city has no matching metro, the app explicitly offers the state average.</p><ol><li><strong>History:</strong> up to 160 EIA weekly observations, using a city series where available or a labeled state/region series.</li><li><strong>Markets:</strong> prior-week changes in WTI crude futures, RBOB gasoline futures, and the XLE energy stock ETF. Daily values are aligned to each historical forecast date; later observations are excluded.</li><li><strong>Model:</strong> a standardized ridge regression predicts the next weekly gas-price change. Its estimate is blended 70/30 with observed local momentum, damped across 14 days, and bounded by historical volatility.</li><li><strong>Three scenarios:</strong> the positive and negative paths use the lower and upper historical forecast-error quantiles, widening over time. The middle path is the central estimate. These are approximate scenarios, not calibrated probability guarantees.</li><li><strong>News:</strong> upward/downward headline keywords add a small bounded stress adjustment. Counts cover only retrieved articles. This heuristic adjustment has not been backtested.</li></ol><p><strong>Validation:</strong> the most recent 16 eligible historical weeks are predicted one at a time using only earlier training data. The dashboard reports their mean absolute error and compares it with holding the previous week's price constant. This evaluates the weekly regression, not the daily interpolation or news adjustment. Missing market feeds are excluded; missing or stale price data suppress projections. No confidence percentage is invented.</p><p>Map markers outside the selected metro use national history for a comparable first estimate. Selecting a metro loads its specific history and recalculates its projections. Futures rollovers, local tax differences, supply shocks, and mismatched survey areas can all affect accuracy.</p></dialog>\n<script src=\"https://unpkg.com/leaflet@1.9.4/dist/leaflet.js\"></script><script src=\"/app.js\"></script></body></html>\n";
const client = "const $=id=>document.getElementById(id);\nconst state={catalog:null,data:null,metros:null,mapData:null,map:null,layer:null,day:1,scenario:'average',historyDays:90,request:0,place:null};\nconst money=(x,digits=3)=>Number.isFinite(x)?'$'+x.toFixed(digits):'—';\nconst cents=x=>Number.isFinite(x)?(x>0?'+':x<0?'−':'')+(Math.abs(x)*100).toFixed(1)+'¢':'—';\nconst dateLabel=d=>new Date(d+'T12:00:00Z').toLocaleDateString('en-US',{timeZone:'UTC',month:'short',day:'numeric'});\nconst norm=s=>String(s||'').toLowerCase().replace(/[^a-z0-9]/g,'');\nconst esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst safeUrl=u=>{try{let x=new URL(u);return x.protocol==='https:'?x.href:'#';}catch{return'#';}};\nfunction status(message,error=false){$('status').textContent=message;$('status').classList.toggle('error',error);}\nasync function api(path,params={}){let url=new URL('/api/'+path,location.origin);Object.entries(params).forEach(([k,v])=>url.searchParams.set(k,v));let r=await fetch(url,{signal:AbortSignal.timeout(65000)});let data=await r.json();if(!r.ok)throw Error(data.error||'Could not load data');return data;}\nfunction chart(el,series,{moneyAxis=true,selected=null,bar=false,height=230}={}){\n let all=series.flatMap(s=>s.points).filter(p=>Number.isFinite(p.value));if(!all.length){el.innerHTML='<div class=\"chart-empty\">No observations available for this period.</div>';return;}\n const w=680,h=height,pad={l:54,r:17,t:15,b:29},times=all.map(p=>Date.parse(p.date+'T12:00:00Z')),minT=Math.min(...times),maxT=Math.max(...times),vals=all.map(p=>p.value);let min=bar?0:Math.min(...vals),max=Math.max(...vals),buffer=Math.max((max-min)*.15,moneyAxis?.02:1);if(!bar)min-=buffer;max+=buffer;\n const x=d=>pad.l+(Date.parse(d+'T12:00:00Z')-minT)/(maxT-minT||1)*(w-pad.l-pad.r),y=v=>pad.t+(max-v)/(max-min||1)*(h-pad.t-pad.b);\n let svg='';for(let i=0;i<4;i++){let v=min+(max-min)*i/3,yy=y(v);svg+=`<line class=\"chart-grid\" x1=\"${pad.l}\" x2=\"${w-pad.r}\" y1=\"${yy}\" y2=\"${yy}\"/><text class=\"chart-axis\" x=\"${pad.l-8}\" y=\"${yy+4}\" text-anchor=\"end\">${moneyAxis?'$'+v.toFixed(2):Math.round(v)}</text>`;}\n if(series.length===3){let high=series[2].points,low=series[0].points;svg+=`<polygon points=\"${high.map(p=>x(p.date)+','+y(p.value)).join(' ')} ${[...low].reverse().map(p=>x(p.date)+','+y(p.value)).join(' ')}\" fill=\"#7091a311\"/>`;}\n for(let s of series){if(bar){let bw=Math.max(4,(w-pad.l-pad.r)/s.points.length*.62);svg+=s.points.map(p=>`<rect x=\"${x(p.date)-bw/2}\" y=\"${y(p.value)}\" width=\"${bw}\" height=\"${Math.max(0,y(0)-y(p.value))}\" rx=\"2\" fill=\"${s.color}\"><title>${esc(p.date)}: ${p.value} articles</title></rect>`).join('');}else svg+=`<polyline class=\"chart-path\" points=\"${s.points.map(p=>x(p.date)+','+y(p.value)).join(' ')}\" stroke=\"${s.color}\" ${s.dash?'stroke-dasharray=\"5 5\"':''}/>`;}\n let dates=[...new Set(all.map(p=>p.date))].sort();for(let i=0;i<5;i++){let d=dates[Math.round(i*(dates.length-1)/4)];svg+=`<text class=\"chart-axis\" x=\"${x(d)}\" y=\"${h-7}\" text-anchor=\"${i===0?'start':i===4?'end':'middle'}\">${dateLabel(d)}</text>`;}\n if(selected){let xx=x(selected);svg+=`<line x1=\"${xx}\" x2=\"${xx}\" y1=\"${pad.t}\" y2=\"${h-pad.b}\" stroke=\"#2a463b\" stroke-dasharray=\"3 4\"/>`;for(let s of series){let p=s.points.find(p=>p.date===selected);if(p)svg+=`<circle cx=\"${xx}\" cy=\"${y(p.value)}\" r=\"4\" fill=\"white\" stroke=\"${s.color}\" stroke-width=\"2\"/>`;}}\n el.innerHTML=`<svg viewBox=\"0 0 ${w} ${h}\" role=\"img\" aria-label=\"${esc(series.map(s=>s.name).join(', '))} chart\" preserveAspectRatio=\"none\">${svg}</svg>`;\n}\nfunction distance(a,b){let rad=Math.PI/180,dlat=(b.lat-a.lat)*rad,dlon=(b.lon-a.lon)*rad,x=Math.sin(dlat/2)**2+Math.cos(a.lat*rad)*Math.cos(b.lat*rad)*Math.sin(dlon/2)**2;return 6371*2*Math.atan2(Math.sqrt(x),Math.sqrt(1-x));}\nfunction matchMetro(places,name,place){let n=norm(name);let exact=places.find(p=>norm(p.name)===n);if(exact)return exact.name;let prefix=places.find(p=>norm(p.name.split(/[-(]/)[0])===n||n==='newyorkcity'&&p.name==='New York');if(prefix)return prefix.name;\n if(place){let available=state.catalog.cities.filter(c=>c.state===place.state&&places.some(p=>norm(c.name)===norm(p.name))).map(c=>({...c,d:distance(c,place)})).sort((a,b)=>a.d-b.d);if(available[0]?.d<80)return available[0].name;}return'';}\nasync function loadState(code,name='',place=null){\n $('state').value=code;status('Retrieving current AAA metro averages…');$('metro').disabled=true;\n try{const prices=await api('state',{state:code});if($('state').value!==code)return;state.metros=prices;let selected=matchMetro(prices.metros,name,place);$('metro').innerHTML='<option value=\"\">'+esc(prices.name)+' · state average</option>'+prices.metros.map(m=>`<option value=\"${esc(m.name)}\">${esc(m.name)}</option>`).join('');$('metro').value=selected;$('metro').disabled=false;state.place=place;await loadCity(code,selected);}\n catch(e){$('metro').disabled=false;status('Could not load this state: '+e.message,true);}\n}\nasync function loadCity(code,name){\n let id=++state.request;document.body.classList.add('loading');status('Loading observed prices, weekly history, markets, and dated news…');\n try{let data=await api('city',{state:code,metro:name});if(id!==state.request)return;state.data=data;try{localStorage.setItem('cheapassgas.location',JSON.stringify({state:code,metro:name}));}catch{}\n if(!data.location){let known=state.catalog.cities.find(c=>c.state===code);data.location=state.place||known||null;if(name){try{let places=await api('geo',{q:name.split('-')[0]+', '+state.catalog.states[code]});if(id!==state.request)return;let p=places.places.find(p=>p.state===code);if(p)data.location=p;}catch{ /* The price table remains usable when geocoding is unavailable. */ }}}\n render();centerMap();status(`${data.coverage==='metro'?'Metro average':'State average fallback'} · ${data.price.name} · AAA as of ${dateLabel(data.price.date)}. ${data.forecast?'14 daily outlooks calculated from observed data.':'Projection unavailable: price data is too old.'}`);\n }catch(e){if(id===state.request)status('Could not load the requested area. '+e.message+' No substitute prices were generated.',true);}\n finally{if(id===state.request)document.body.classList.remove('loading');}\n}\nfunction render(){const d=state.data;if(!d)return;$('title').textContent=d.price.name+' fuel outlook';$('subtitle').textContent=(d.coverage==='metro'?'Published metro area':'State fallback')+' · '+state.catalog.states[d.price.state]+' · regular gasoline';$('price').textContent=money(d.price.current);$('priceDate').innerHTML=`<a href=\"${safeUrl(d.source)}\" target=\"_blank\" rel=\"noopener\">AAA · ${esc(d.price.date)}</a> · ${d.coverage} average`;\n let week=d.price.current-d.price.week;$('weekChange').textContent=Number.isFinite(week)?cents(week):'—';$('weekChange').className='metric-number '+(week>0?'up':'down');$('monthChange').textContent=d.price.month?cents(d.price.current-d.price.month)+' vs month ago':'Month comparison unavailable';\n let validation=d.forecast?.validation;$('validation').textContent=validation?(validation.mae*100).toFixed(1)+'¢ / gallon':'Not measured';$('validationDetail').textContent=validation?`${validation.weeks} held-out weekly predictions; unchanged-price baseline ${(validation.baselineMAE*100).toFixed(1)}¢. Daily/news paths not backtested.`:'Insufficient aligned history for validation.';\n $('forecastNote').textContent=d.forecast?`${d.forecast.method} · ${d.forecast.priceAgeDays?'Starting observation is '+d.forecast.priceAgeDays+' day(s) old. ':''}Scenario widths reflect past weekly forecast errors; daily paths are interpolated estimates.`:'Projections are suppressed when the starting price is more than 14 days old.';\n $('dailyTable').innerHTML=d.forecast?d.forecast.points.map((p,i)=>`<tr data-day=\"${i}\" tabindex=\"0\"><td>${i===0?'Today · ':''}${dateLabel(p.date)}</td><td class=\"down\">${money(p.positive)}</td><td>${money(p.average)}</td><td class=\"up\">${money(p.negative)}</td></tr>`).join(''):'<tr><td colspan=\"4\">No fresh starting price available.</td></tr>';\n $('dailyTable').querySelectorAll('tr[data-day]').forEach(row=>{let choose=()=>{$('day').value=row.dataset.day;state.day=+row.dataset.day;renderDay();};row.onclick=choose;row.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose();}};});\n $('drivers').innerHTML=d.forecast?d.forecast.drivers.map(x=>`<div class=\"driver\"><span>${esc(x.name)}</span><strong class=\"${x.weekly>0?'up':'down'}\">${cents(x.weekly)}</strong></div>`).join(''):'No model is available.';\n $('modelScope').textContent=`History coverage: ${d.history.description} (${d.history.scope}). ${d.forecast?.validation?.trainingWeeks||0} aligned weekly training observations. Local changes are compared with ${d.coverage} snapshots.`;\n let missing=d.signals.errors,news=d.signals.news;$('dataIssues').textContent=(missing.length?'Unavailable feeds: '+missing.join('; ')+'. ':'')+(news?.providers.length?'News sources: '+news.providers.join(', ')+'. ':'News feed unavailable. ')+(d.history.scope!=='city'?'Historical series covers a broader area than this metro.':'City-level historical series available.');$('dataIssues').classList.toggle('error',missing.length>0);\n renderDay();renderHistory();renderMarkets();renderNews();$('retrieval').textContent=' Prices retrieved '+new Date(d.retrievedAt).toLocaleString('en-US')+'.';\n}\nfunction renderDay(){let d=state.data,p=d?.forecast?.points[state.day];$('dayLabel').textContent=p?dateLabel(p.date)+(state.day===0?' · today':' · +'+state.day+' days'):'Unavailable';for(let key of ['positive','average','negative'])$(key).textContent=p?money(p[key]):'—';$('estimate').textContent=p?money(p.average):'—';$('estimateDetail').textContent=p?dateLabel(p.date)+' · computed central scenario':'No projection available';$('estimateLabel').textContent='Average projection · '+(state.day===0?'today':'+'+state.day+' days');\n if(d?.forecast)chart($('forecastChart'),[{name:'Positive lower price',color:'#257657',dash:true,points:d.forecast.points.map(p=>({date:p.date,value:p.positive}))},{name:'Average projected price',color:'#547eab',points:d.forecast.points.map(p=>({date:p.date,value:p.average}))},{name:'Negative higher price',color:'#b75344',dash:true,points:d.forecast.points.map(p=>({date:p.date,value:p.negative}))}],{selected:p.date});else $('forecastChart').innerHTML='<div class=\"chart-empty\">Forecast unavailable.</div>';\n $('dailyTable').querySelectorAll('tr[data-day]').forEach(row=>row.classList.toggle('active',+row.dataset.day===state.day));$('mapDate').textContent=p?dateLabel(p.date)+' · '+state.scenario+' scenario · USD / gallon':'Observed prices';renderMap();\n}\nfunction renderHistory(){let d=state.data;if(!d)return;let cutoff=new Date(Date.now()-state.historyDays*86400000).toISOString().slice(0,10),points=d.history.points.filter(p=>p.date>=cutoff);chart($('historyChart'),[{name:'EIA weekly regular gas',color:'#257657',points}]);$('historyScope').textContent=d.history.description+' · '+d.history.scope+' series · weekly, USD / gallon';$('historyDate').innerHTML=`<a target=\"_blank\" rel=\"noopener\" href=\"${safeUrl(d.history.url)}\">EIA source</a> · ${points.length} actual observations · latest ${esc(d.history.points.at(-1)?.date||'unavailable')}. AAA and EIA survey different areas; the historical chart is not relabeled as the metro's daily history.`;}\nfunction renderMarkets(){let markets=state.data.signals.markets;$('marketGrid').innerHTML=markets.map((m,i)=>{let a=m.points.at(-1),prior=[...m.points].reverse().find(p=>p.date<=new Date(Date.parse(a.date)-7*86400000).toISOString().slice(0,10));let change=prior?(a.value/prior.value-1)*100:0;return `<article class=\"card market-card\"><div class=\"market-top\"><h3>${esc(m.label)}</h3><a href=\"${safeUrl(m.url)}\" target=\"_blank\" rel=\"noopener\" class=\"pill\">SOURCE ↗</a></div><div class=\"market-num\">${money(a.value,m.symbol==='RB=F'?3:2)}</div><div class=\"market-change ${change>0?'up':'down'}\">${change>=0?'+':''}${change.toFixed(2)}% over 7 calendar days</div><div class=\"chartbox\" id=\"market-${i}\"></div><div class=\"map-note market-bottom\">${esc(m.unit)} · ${esc(m.asOf)}${m.adjusted?' · split/dividend adjusted history':''}</div></article>`;}).join('')||'<div class=\"card\">Market feeds are unavailable. No values have been substituted.</div>';let cutoff=new Date(Date.now()-90*86400000).toISOString().slice(0,10);markets.forEach((m,i)=>chart($('market-'+i),[{name:m.label,color:'#6a8b74',points:m.points.filter(p=>p.date>=cutoff)}],{height:110}));}\nfunction renderNews(){let news=state.data.signals.news;if(!news){$('newsChart').innerHTML='<div class=\"chart-empty\">News feeds unavailable.</div>';$('newsList').innerHTML='<li>News feeds unavailable.</li>';return;}\n chart($('newsChart'),[{name:'Retrieved headlines per day',color:'#72947a',points:news.days.map(d=>({date:d.date,value:d.count}))}],{moneyAxis:false,bar:true,height:145});$('newsUp').textContent=news.up;$('newsDown').textContent=news.down;$('newsTotal').textContent=news.articles.filter(a=>a.date>=news.days[7].date).length;$('newsScope').textContent=`Last 7 days: headline keyword cues. ${news.scope} ${news.errors.length?'Primary-feed failure is disclosed; available publisher feeds are used.':''}`;$('newsSource').textContent=news.providers.join(' + ')+' · '+news.articles.length+' recent feed articles';$('newsList').innerHTML=news.articles.slice(0,6).map(a=>`<li><a href=\"${safeUrl(a.url)}\" target=\"_blank\" rel=\"noopener\">${esc(a.title)}</a><div class=\"news-meta\">${esc(a.publisher)} · ${esc(a.date)} · ${a.cue>0?'upward cue':a.cue<0?'downward cue':'neutral/mixed cue'}</div></li>`).join('')||'<li>No recent articles were returned. No media trend was inferred.</li>';\n}\nfunction initMap(){if(!window.L){$('map').innerHTML='<div class=\"chart-empty\">Map library could not load. Price charts and tables remain available.</div>';return;}state.map=L.map('map',{scrollWheelZoom:false}).setView([39.5,-98.35],4);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href=\"https://www.openstreetmap.org/copyright\">OpenStreetMap</a> contributors'}).addTo(state.map);state.layer=L.layerGroup().addTo(state.map);}\nfunction renderMap(){if(!state.map)return;state.layer.clearLayers();let cities=state.mapData?.cities?[...state.mapData.cities]:[];let d=state.data;if(d?.location){let selected={...d.location,name:d.price.name,state:d.price.state,price:d.price,forecast:d.forecast,selected:true,source:d.source};cities=cities.filter(c=>!(c.state===selected.state&&norm(c.name)===norm(selected.name)));cities.push(selected);}\n for(let c of cities){let p=c.forecast?.points[state.day],value=p?.[state.scenario]||c.price.current,icon=L.divIcon({html:`<div class=\"price-pin ${esc(state.scenario)} ${c.selected?'selected':''}\">${money(value,2)}</div>`,className:'',iconSize:[66,29],iconAnchor:[33,14]});let marker=L.marker([c.lat,c.lon],{icon,title:c.name+': '+money(value),keyboard:true}).addTo(state.layer);let popup=document.createElement('div');popup.innerHTML=`<h3>${esc(c.name)}, ${esc(c.state)}</h3><p>${p?'Projected '+dateLabel(p.date)+' · '+esc(state.scenario):'Observed AAA price'}<br><strong>${money(value)} / gallon</strong><br>Observed ${money(c.price.current)} · ${esc(c.price.date)}</p><a href=\"${safeUrl(c.source)}\" target=\"_blank\" rel=\"noopener\">AAA source ↗</a><br>`;if(!c.selected){let button=document.createElement('button');button.textContent='Explore this metro';button.style.marginTop='10px';button.onclick=()=>loadState(c.state,c.name);popup.append(button);}marker.bindPopup(popup);}\n $('mapCount').textContent=cities.length+' METROS';$('mapNote').textContent=(state.mapData?`${state.mapData.cities.length} matched AAA major metros. Other markers use national historical calibration; selecting a metro recalculates with its city/region history. `:'Selected metro loaded; nationwide markers are loading. ')+(state.mapData?.failedStates.length?'Unavailable state feeds: '+state.mapData.failedStates.join(', '):'')+' Map values change with day and scenario.';\n}\nfunction centerMap(){if(state.map&&state.data?.location){state.map.flyTo([state.data.location.lat,state.data.location.lon],7,{duration:.6});}}\nasync function loadMap(){try{state.mapData=await api('map');renderMap();}catch(e){$('mapNote').textContent='Nationwide map feed unavailable: '+e.message+'. Selected area remains shown.';$('mapCount').textContent='PARTIAL';}}\nasync function start(){try{state.catalog=await api('catalog');$('state').innerHTML=Object.entries(state.catalog.states).sort((a,b)=>a[1].localeCompare(b[1])).map(([code,name])=>`<option value=\"${code}\">${esc(name)}</option>`).join('');initMap();let saved;try{saved=JSON.parse(localStorage.getItem('cheapassgas.location'));}catch{}let code=state.catalog.states[saved?.state]?saved.state:'NY',metro=saved?.metro||'New York';await loadState(code,metro);await loadMap();}catch(e){status('Could not initialize data services: '+e.message,true);}}\n$('state').onchange=()=>loadState($('state').value);$('metro').onchange=()=>loadCity($('state').value,$('metro').value);$('day').oninput=e=>{state.day=+e.target.value;renderDay();};$('scenario').onchange=e=>{state.scenario=e.target.value;renderDay();};$('centerMap').onclick=centerMap;$('allMap').onclick=()=>state.map?.flyTo([39.5,-98.35],4);$('refresh').onclick=async()=>{await loadCity($('state').value,$('metro').value);await loadMap();};$('methodBtn').onclick=()=>$('method').showModal();$('closeMethod').onclick=()=>$('method').close();$('method').onclick=e=>{if(e.target===$('method'))$('method').close();};\ndocument.querySelectorAll('#historyTabs button').forEach(b=>b.onclick=()=>{state.historyDays=+b.dataset.days;document.querySelectorAll('#historyTabs button').forEach(x=>x.classList.toggle('active',x===b));renderHistory();});\n$('searchForm').onsubmit=async e=>{e.preventDefault();let q=$('query').value.trim();if(!q)return;status('Searching US cities and ZIP codes…');try{let result=await api('geo',{q});$('searchResults').replaceChildren();if(!result.places.length){status('No US location found. Choose a state and metro below.',true);return;}for(let p of result.places){let b=document.createElement('button');b.textContent=p.label;b.onclick=()=>{$('searchResults').replaceChildren();loadState(p.state,p.name,p);};$('searchResults').append(b);}status('Choose your location from the matches above.');}catch(e){status('Search unavailable: '+e.message+'. State and metro selectors remain available.',true);}};\n$('locate').onclick=()=>{if(!navigator.geolocation){status('Location is unavailable in this browser. Use city search.',true);return;}status('Requesting your location…');navigator.geolocation.getCurrentPosition(async position=>{try{let place=await api('reverse',{lat:position.coords.latitude,lon:position.coords.longitude});await loadState(place.state,place.name,place);}catch(e){status(e.message+' Use city search or choose a state.',true);}},()=>status('Location permission was unavailable. Use city search or the metro selector.',true),{enableHighAccuracy:false,timeout:15000,maximumAge:300000});};\nstart();\n";
const headers={'x-content-type-options':'nosniff','referrer-policy':'strict-origin-when-cross-origin'};
const json=(data,status=200)=>new Response(JSON.stringify(data),{status,headers:{...headers,'content-type':'application/json; charset=utf-8','cache-control':'no-store'}});
export default {
 async fetch(request,env,ctx){
  if(request.method!=='GET')return json({error:'Use GET'},405);
  let url=new URL(request.url),path=url.pathname;
  if(path==='/')return new Response(page,{headers:{...headers,'content-type':'text/html; charset=utf-8'}});
  if(path==='/app.js')return new Response(client,{headers:{...headers,'content-type':'text/javascript; charset=utf-8','cache-control':'public,max-age=60'}});
  if(path==='/favicon.ico')return new Response(null,{status:204});
  try{
   if(path==='/api/catalog')return json({states:STATES,cities:CITIES});
   if(path==='/api/geo'){let q=url.searchParams.get('q')?.trim();if(!q||q.length>100)return json({error:'Enter a US city or ZIP code (up to 100 characters).'},400);return json({places:await geocode(q,ctx)});}
   if(path==='/api/reverse'){let lat=Number(url.searchParams.get('lat')),lon=Number(url.searchParams.get('lon'));if(!Number.isFinite(lat)||!Number.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180)return json({error:'Invalid coordinates'},400);let data=await cached('reverse-'+lat.toFixed(3)+'-'+lon.toFixed(3),604800,ctx,async()=>{let response=await fetch(`https://photon.komoot.io/reverse?lat=${lat}&lon=${lon}&limit=1`,{signal:AbortSignal.timeout(10000)});if(!response.ok)throw Error('Location service unavailable');let raw=await response.json(),p=raw.features?.[0]?.properties;if(p?.countrycode!=='US')throw Error('US gas prices are supported currently.');let state=Object.entries(STATES).find(([code,name])=>name===p.state||code===p.state)?.[0];if(!state)throw Error('Could not resolve a US state.');return {name:p.city||p.name||p.county,state,lat,lon};});return json(data);}
   if(path==='/api/map')return json(await mapData(ctx));
   if(path==='/api/state'||path==='/api/city'){let state=url.searchParams.get('state')||'NY';if(!STATES[state])return json({error:'Choose a valid US state.'},400);let metro=url.searchParams.get('metro')||'';if(metro.length>140)return json({error:'Metro name too long'},400);if(path==='/api/state')return json(await statePrices(state,ctx));return json(await cityData(state,metro,ctx));}
   return json({error:'Not found'},404);
  }catch(e){console.error(JSON.stringify({route:path,message:e.message}));return json({error:e.message||'Data service unavailable. Please retry.',status:'unavailable'},502);}
 }
};
